WHO = {'column': [('temmewei', 96483), ('aprillhisha', 96547), ('muefleewei', 0), ('renmaocren', 96739), ('zecyfeyeben', 96739), ('romulcyeben', 96739), ('psilocewei', 96739), ('apriehisha', 0)], 'temple': [('zecyflecut', 96547), ('mucocuya', 100259), ('aprillhisha', 101539), ('temmewei', 0), ('zecyflecut', 108010), ('mulceceyeben', 108778), ('kisen', 109930), ('mucocuya', 0)], 'tower': [('alphafcyeben', 0), ('brideeyeben', 98403), ('brideum', 0), ('eindeeyeben', 0), ('mulceceyeben', 0), ('brideeyeben', 0)], 'tree': [('aprilfools', 0), ('seneecefools', 96803), ('mueflewei', 96995), ('seneecefools', 0), ('shathisha', 0), ('eindeewei', 97763), ('mulcfools', 98467), ('renmaeyeben', 0)], 'manor': [('renmaeyeben', 0), ('seneechisha', 99875), ('rosehceyeben', 103523), ('psilocewei', 103651), ('temmewei', 104423), ('seneecuya', 104551), ('zecyfocren', 106602), ('muefools', 106858)], 'bridge': [('alphafoldmicro', 101987), ('alphafoldmicro', 102307), ('alphafolhlso', 102755), ('alphafolhlso', 0), ('alphafoldmicro', 105834), ('aprielhlsof', 107754), ('alphafoldmicro', 110186)], 'castle': [('mulceewei', 103715)]}

EPI_RX = re.compile(
    r"^(?:what (?:has|have) (?P<a>[\w'\- ]{2,24}?) (?:done|been doing)"
    r"|what happened (?:with|to) (?P<b>[\w'\- ]{2,24}?))[?.! ]*$", re.I)
WHO_RX = re.compile(
    r"^who (?:built|made|raised) (?:a |an |the )?(?P<k>[\w \-]{2,24}?)[?.! ]*$", re.I)


class OracleReleaseRuntimeW307(OracleReleaseRuntimeW305):
    """Base + episodic recall. Fires only on bound episodes; else the chain answers."""

    def chat(self, text: str, session_id: str = "default") -> dict:
        s = " ".join(str(text).strip().split())
        m = EPI_RX.match(s)
        if m:
            actor = (m.group("a") or m.group("b") or "").strip().lower()
            eps = EPI.get(actor)
            if eps:
                bits = "; ".join(f"at tick {t} {v} {o}" for t, v, o in eps[-5:])
                pending = getattr(self, "_pending_conversion", None)
                if pending is None:
                    pending = self._pending_conversion = {}
                pending[session_id] = {"construction": "EPISODIC_RECALL",
                                        "from": s[:80], "to": f"episodes({actor})",
                                        "produced_by": "oracle_fold_worker_v4"}
                return {"status": "answered", "path": "worker:episodic",
                         "response": f"The record holds for {actor}: {bits}. "
                                     f"[world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "actor": actor,
                                         "episodes": len(eps)},
                         "latency_ms": 1}
        w = WHO_RX.match(s)
        if w:
            kind = w.group("k").strip().lower()
            hits = WHO.get(kind) or WHO.get(kind.rstrip("s"))
            if hits:
                bits = ", ".join(f"{a} (tick {t})" for a, t in hits[-4:])
                return {"status": "answered", "path": "worker:episodic_who",
                         "response": f"By the world record, {kind}s were raised by "
                                     f"{bits}. [world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "object": kind},
                         "latency_ms": 1}
        return super().chat(s, session_id)
